WITH lines AS (SELECT id, host, log_ts, level, latency_ms, status_code, key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) e AS key, attr_value), unpacked AS (SELECT latency_ms, status_code, key, SHIFTRIGHT(status_code, 2) AS status_code_high, CAST((status_code & 4) != 0 AS INT) AS has_fault FROM lines), metrics AS (SELECT *, CORR(status_code, latency_ms) OVER w_ordered AS corr_status_code_latency_ms, MAX(status_code_high) OVER w_ordered AS key_max_status_code_high FROM unpacked WINDOW w_ordered AS (PARTITION BY key)), cleaned AS (SELECT *, INITCAP(TRIM(key)) AS key_title FROM metrics WHERE has_fault < 0) SELECT latency_ms, status_code, status_code_high, has_fault, corr_status_code_latency_ms, key_max_status_code_high, key_title FROM cleaned ORDER BY latency_ms ASC NULLS FIRST, corr_status_code_latency_ms DESC
